def find_path(graph, start, goal):
    priority_queue = [(0, start)]
    visited = set()
    cost_and_path = {start: (0, [start])}
    while priority_queue:
        current_cost, current_node = heapq.heappop(priority_queue)
        if current_node == goal:
            return cost_and_path[goal][1]
        visited.add(current_node)
        for neighbor in graph.get(current_node, []):
            if neighbor in visited:
                continue
            tentative_cost = current_cost + 1
            if neighbor not in cost_and_path or tentative_cost < cost_and_path[neighbor][0]:
                cost_and_path[neighbor] = (tentative_cost, cost_and_path[current_node][1] + [neighbor])
                heapq.heappush(priority_queue, (tentative_cost, neighbor))
    return None
