import heapq

def find_path(graph, start, goal):
    # If the graph is not a dictionary, convert it to a default dictionary
    if not isinstance(graph, defaultdict):
        graph = defaultdict(list, graph)

    # Dijkstra's algorithm
    def dijkstra(graph, start, goal):
        if start not in graph or goal not in graph:
            return None

        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        queue = [(0, start)]
        visited = set()

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_node == goal:
                return distances[goal]

            if current_node in visited:
                continue

            visited.add(current_node)

            for neighbor, edge_weight in graph[current_node]:
                distance = current_distance + edge_weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))

        return None

    # A* algorithm
    def a_star(graph, start, goal):
        if start not in graph or goal not in graph:
            return None

        g_scores = {node: float('inf') for node in graph}
        g_scores[start] = 0
        f_scores = {node: float('inf') for node in graph}
        f_scores[start] = 0

        open_set = [(0, start)]
        came_from = {}

        while open_set:
            _, current_node = heapq.heappop(open_set)

            if current_node == goal:
                path = []
                while current_node in came_from:
                    path.append(current_node)
                    current_node = came_from[current_node]
                path.append(start)
                path.reverse()
                return path

            if current_node in visited:
                continue

            visited.add(current_node)

            for neighbor, edge_weight in graph[current_node]:
                tentative_g_score = g_scores[current_node] + edge_weight

                if tentative_g_score < g_scores[neighbor]:
                    came_from[neighbor] = current_node
                    g_scores[neighbor] = tentative_g_score
                    f_scores[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                    heapq.heappush(open_set, (f_scores[neighbor], neighbor))

        return None

    # Since the heuristic is not provided, we will default to a simple heuristic
    # that suggests moving towards the goal in a straight line (Manhattan distance).
    heuristic = lambda node, goal: abs(node[0] - goal[0]) + abs(node[1] - goal[1])

    # Perform search
    path = dijkstra(graph, start, goal)
    if path is not None:
        return path
    path = a_star(graph, start, goal)
    if path is not None:
        return path

    return None

