def find_path(graph, start, goal):
    distances = {node: {neighbor: float('inf') for neighbor in graph} for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            distances[node][neighbor] = graph[node][neighbor]
            distances[neighbor][node] = graph[node][neighbor]
    for k in graph:
        for i in graph:
            for j in graph:
                distances[i][j] = min(distances[i][j], distances[i][k] + distances[k][j])
    if goal not in distances[start]:
        return None
    path = [goal]
    while path[-1] != start:
        for node in distances[path[-1]]:
            if distances[path[-1]][node] + distances[node][path[-1]] == distances[path[-1]][goal]:
                path.append(node)
                goal = node
                break
    path.append(start)
    path.reverse()
    return path
